/* Integrated planning workspace. All operations are server checked. */
(()=>{'use strict';
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const value=id=>document.getElementById(id)?.value;
const cycle=()=>value('jop_cycle')?.trim();let plan=null,planVersion=null,loadedCycle=null,busy=false,availableCalls=[],availablePlans=[];
async function request(query='',body=null){const {data:{session}}=await supabaseClient.auth.getSession();if(!session?.access_token)throw Error('Inicia sesión de nuevo.');const r=await fetch('/api/academic-lifecycle'+query,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await jaguarReadJson(r);if(!r.ok||!d.ok)throw Error(d.error||'Operación no disponible.');return d.data;}
function html(selected=""){
 const ce=['control_escolar','control','direccion_escolar'].includes(S.role),academic=['direccion_escolar','coordinacion_academica'].includes(S.role);
 const btn=(label,action)=>`<button type="button" class="btn" onclick="jaguarOperations.${action}">${E(label)}</button>`;
 const panel=(key,content,first=false)=>`<section data-jl-panel="ops" data-jl-key="${key}" ${first?'':'hidden'} class="space-y-3">${content}</section>`;
 const tabs=[['trajectory','Trayectoria del alumno'],['regularization','Convocatorias'],['opening','Apertura de ciclo'],...(ce?[['movements','Movimientos y reinscripción']]:[]),...(academic?[['workload','Carga docente']]:[]),['institution','Gobierno y horarios']];
 return `<section class="card space-y-3"><h3>Herramientas de gestión</h3><p>Selecciona el ciclo y, cuando se requiera, el expediente. Las actuaciones autorizadas conservan sus requisitos documentales y permisos.</p><div class="grid md:grid-cols-2 gap-3"><label>Ciclo escolar <input id="jop_cycle" class="input" value="${E(selected)}" placeholder="2026-2027/1" title="AAAA-AAAA o AAAA-AAAA/N" pattern="[0-9]{4}-[0-9]{4}(?:/[1-9])?" onchange="jaguarOperations.reset()"></label><label>ID interno de alumno (para consultas individuales)<input id="jop_student" class="input" inputmode="numeric" placeholder="ID del expediente, no matrícula"></label></div><nav class="jl-nav" aria-label="Herramientas avanzadas">${tabs.map(([key,title],i)=>`<button type="button" class="btn${i===0?' primary':''}" data-jl-nav="ops" data-jl-key="${key}" aria-pressed="${i===0}" onclick="jaguarLifecycle.switchTab('ops','${key}')">${E(title)}</button>`).join('')}</nav>
 ${panel('trajectory',`<div class="card space-y-2"><h4>Acreditación y trayectoria</h4>${btn('Evaluar acreditación proyectada','project()')} ${btn('Consultar sellos históricos','project(true)')}<div id="jop_projection"></div>${btn('Consultar trayectoria con actas','trajectory()')}<div id="jop_trajectory"></div>${btn('Consultar informe histórico detallado','historicalReport(false)')} ${btn('Descargar informe histórico CSV','historicalReport()')}<div id="jop_report"></div>${btn('Consultar continuidad escolar','continuity()')}<div id="jop_continuity"></div>${ce?btn('Consultar formalización de egreso','egress()')+'<div id="jop_egress"></div>':''}</div>`,true)}
 ${panel('regularization',`<div class="card space-y-2"><h4>Recuperación y recursamiento</h4>${btn('Consultar convocatorias y plan','calls()')}<div id="jop_calls"></div></div>`)}
 ${panel('opening',`<div class="card space-y-2"><h4>Apertura de ciclo · operación restringida</h4><p>Indica el ciclo de destino. El servidor exige todos los sellos del origen y grupos de destino vacíos, previamente vinculados. No cambia de grupo a ningún alumno. No se habilitan escrituras adicionales desde este menú.</p>${btn('Revisar apertura de ciclo','cycleOpening()')}<div id="jop_opening"></div></div><div class="card space-y-2"><h4>Ingreso extraordinario · obligaciones previas</h4><p>Preparación contra el plan validado; no inscribe alumnos ni registra calificaciones.</p><label>Grado <select id="jop_late_grade" class="input"><option value="1">Primero</option><option value="2">Segundo</option><option value="3">Tercero</option></select></label><label>Fecha efectiva de ingreso <input id="jop_late_date" type="date" class="input"></label>${btn('Preparar obligaciones de ingreso','lateEntry()')}<div id="jop_late_result"></div></div>`)}
 ${ce?panel('movements',`<div class="card space-y-2"><h4>Bajas, traslados y reincorporación</h4><p>Operación restringida a grupos vinculados y fuera del intervalo de clases. No emite cartas ni revoca cuentas.</p><label>Tipo <select id="jop_move_type" class="input" onchange="jaguarOperations.clearMovement()"><option value="baja">Baja</option><option value="traslado">Traslado de salida</option><option value="retorno">Reincorporación</option></select></label><label id="jop_move_target_label" hidden>Grupo destino (ID)<input id="jop_move_target" class="input" inputmode="numeric" onchange="jaguarOperations.clearMovement()"></label>${btn('Consultar movimiento escolar','schoolMovement()')}<div id="jop_move_status"></div></div><div class="card space-y-2"><h4>Reinscripción y grupo de destino</h4><p>Para vincular, indica el ciclo de destino. Para reinscribir, indica ciclo de origen y alumno. Alcance actual: promoción o repetición completa antes de iniciar clases.</p><label>ID interno del grupo destino<input id="jop_enroll_group" class="input" inputmode="numeric"></label>${btn('Consultar vínculo de grupo','cycleGroup()')}<div id="jop_group_status"></div>${btn('Consultar reinscripción','reenrollment()')}<div id="jop_enroll_status"></div></div>`):''}
 ${academic?panel('workload',`<div class="card space-y-2"><h4>Carga docente del horario registrado</h4>${btn('Analizar horarios','workload()')}<div id="jop_workload"></div></div>`):''}
 ${panel('institution',window.jaguarInstitution?.html()||'<p>Herramientas de gobierno no disponibles.</p>')}</section>`}
function reset(){movementCache=null;recoveryCache={};window.jaguarInstitution?.reset();candidateCache.clear();temporaryCache.clear();plan=null;planVersion=null;loadedCycle=null;availableCalls=[];availablePlans=[];for(const id of ['jop_opening','jop_projection','jop_trajectory','jop_report','jop_continuity','jop_egress','jop_move_status','jop_group_status','jop_enroll_status','jop_late_result','jop_calls','jop_workload']){const el=document.getElementById(id);if(el)el.textContent='';}}
function query(view){const c=cycle();if(!/^\d{4}-\d{4}(?:\/[1-9])?$/.test(c||''))throw Error('Indica el ciclo escolar.');return '?view='+view+'&cycle='+encodeURIComponent(c)}
async function show(id,fn){if(busy)return;const el=document.getElementById(id),c=cycle();if(!el)return;busy=true;el.textContent='Consultando…';try{const output=await fn();if(el.isConnected&&c===cycle())el.innerHTML=output;}catch(e){if(el.isConnected&&c===cycle())el.textContent=e.message;}finally{busy=false;}}
async function project(sealed=false){await show('jop_projection',async()=>{const student=value('jop_student')?.trim();if(!/^[1-9]\d{0,18}$/.test(student||''))throw Error('ID interno inválido.');const d=await request(query(sealed?'sealed_projection':'projection')+'&student='+encodeURIComponent(student));return `<p><b>${d.state==='projected'?'Proyección calculada':'Expediente con pendientes de conciliación'}</b> · Plan V${E(d.planVersion)}</p><p>${E(d.mapping)}</p><p>${(d.periods||[]).map(p=>`P${E(p.number)}: ${p.verified?'vigente':'sin verificación vigente'}`).join(' · ')}</p>${d.reason?`<p>Revisión requerida: ${E(d.reason)}</p>`:''}${(d.subjects||[]).map(s=>`<details class="card"><summary>${E(s.name)} · ${E(({accredited:'Cumple',candidate:'Candidato a regularización',pending:'Pendiente',not_applicable:'Sin evaluación'})[s.state]||s.state)}</summary>${s.points!=null?`<p>Puntos: ${E(s.points)} / ${E(s.pointsRequired)}</p>`:''}<p>${E(s.reason||'')}</p><p>Bloques sugeridos: ${E((s.suggestedBlocks||[]).join(', ')||'Por determinar')}${s.needsBlockReview?' · requiere revisión de Coordinación':''}</p>${s.cumulative?`<p>Asistencia: ${E(s.cumulative.valid)} / ${E(s.cumulative.required)} mínimas exigidas</p>`:''}</details>`).join('')}<p>Trayectoria proyectada: ${E(d.trajectory?.state||'pendiente')}. No es promoción oficial.</p>`;});}
let trajectoryCache=null;
const trajectoryStates={promote:'Elegible para promoción',academic_completion:'Conclusión académica del último grado',repeat_grade:'Repetir grado',repeat_subjects:'Repetir materias pendientes',await_regularization:'Regularización pendiente',pending:'Expediente pendiente'};
async function trajectory(){trajectoryCache=null;await show('jop_trajectory',async()=>{const student=value('jop_student')?.trim(),c=cycle();if(!/^[1-9]\d{0,18}$/.test(student||''))throw Error('ID interno inválido.');const d=await request(query('trajectory_review')+'&student='+encodeURIComponent(student));if(student!==value('jop_student')?.trim()||c!==cycle())return 'Vuelve a consultar.';trajectoryCache={student,cycle:c,d};return `<h4>Trayectoria con actas de recursamiento</h4><p>Plan V${E(d.planVersion)} · ${E(trajectoryStates[d.trajectory?.state]||d.trajectory?.state||'Pendiente')}.</p>${(d.subjects||[]).map(s=>`<p>${E(s.name)}: ${E(({accredited:'Cumple',candidate:'No acreditada',pending:'Pendiente',not_applicable:'Sin evaluación'})[s.state]||s.state)}${s.attemptExhausted?' · intento registrado':''}${s.attendanceReleased?' · adeudo de asistencia liberado':''}${s.points!=null?' · '+E(s.points)+' puntos':''}</p>`).join('')}${(d.applications||[]).map((a,i)=>`<div class="card space-y-2"><b>${E(a.name)} · Acta ${E(a.call)}</b><p>${E(({authorized:'Aplicación de prueba autorizada',proposed:'Propuesta pendiente de Dirección',review:'Revisión requerida',not_recorded:'Sin aplicación registrada'})[a.status]||a.status)}</p>${a.error?`<p>${E(a.error)}</p>`:''}${a.proposal?`<p>Resultado calculado: ${E(a.proposal.result.state==='accredited'?'Cumple':'No acredita')} · ${a.proposal.attendanceReleased?'Liberación de adeudo de asistencia.':'Sin liberación adicional de asistencia.'}</p>${a.proposal.changes.map(x=>`<p>P${E(x.period)}: ${E(x.before.official??x.before.result)} → ${E(x.after.official??x.after.result)}</p>`).join('')}`:''}${a.reference?`<p>Referencia: ${E(a.reference)} · ${E(a.actor)}</p>`:''}${d.experimental&&(a.canPropose&&['control_escolar','control'].includes(S.role)||a.canAuthorize&&S.role==='direccion_escolar')?`<button type="button" class="btn primary" onclick="jaguarOperations.applyRecourse(${i})">${a.canPropose?'Proponer aplicación experimental':'Autorizar aplicación experimental'}</button>`:''}</div>`).join('')}<p>Libro experimental. No modifica boletas, inscripciones ni promociones oficiales. Las notas mostradas conservan la escala exacta; falta integrar su precisión de presentación.</p>`;});}
async function applyRecourse(i){const c=trajectoryCache,a=c?.d.applications[i];if(busy||!a||!c.d.experimental||c.student!==value('jop_student')?.trim()||c.cycle!==cycle())return;const operation=a.canPropose?'proponer':a.canAuthorize?'autorizar':null;if(!operation)return;const reference=prompt('Referencia documental (5 a 300 caracteres)');if(!reference||reference.trim().length<5)return;const reason=prompt('Motivo documentado (15 a 1500 caracteres)');if(!reason||reason.trim().length<15||!confirm('¿Registrar esta aplicación experimental sin modificar notas ordinarias?'))return;busy=true;try{await request('',{action:'apply_recourse',operation,call:a.call,student:c.student,cycle:c.cycle,fingerprint:c.d.fingerprint,reference,reason,confirmed:true});toast('Aplicación experimental registrada.');}catch(e){toast(e.message);return;}finally{busy=false;}await trajectory();}
function historicalTable(d){
 const status={accredited:'Cumple',candidate:'No acreditada',pending:'Pendiente',not_applicable:'Sin evaluación'};
 const display=v=>v==null?'—':E(v);
 const periods=Array.isArray(d.periods)?d.periods:[];
 const cell=(r)=>r?`<div>Sellada: ${display(r.sealed)}</div><div>Ordinaria vigente: ${display(r.ordinary)}</div><div><b>Efectiva: ${display(r.effective)}</b></div>${r.rectification?'<small>Rectificación autorizada</small>':''}${r.recoveryCalls?'<small> · Recuperación</small>':''}${r.act?'<small> · Recursamiento</small>':''}${r.attendanceReleased?'<small> · Adeudo de asistencia liberado (experimental)</small>':''}`:'Sin evidencia conciliada';
 const subjects=Array.isArray(d.subjects)?d.subjects:[];
 const grid=subjects.length&&periods.length?`<div style="overflow-x:auto"><table class="table"><thead><tr><th>Asignatura / estado</th>${periods.map(p=>`<th>P${E(p.number)}<br>${p.verified?'Sellado':'Sin sello'}</th>`).join('')}</tr></thead><tbody>${subjects.map(s=>`<tr><th>${E(s.name)}<br><small>${E(status[s.state]||'Pendiente')}</small></th>${periods.map(p=>{const rows=d.rows.filter(r=>r.subjectKey===s.key&&r.period===p.number);return `<td>${s.evaluation==='no_aplica'?'No aplica':rows.length>1?'Evidencia ambigua':cell(rows[0])}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`:'<p>Grado o plan sin conciliación completa; consulta las evidencias disponibles.</p>';
 return `<p>Alumno ID ${E(d.student)} · Ciclo ${E(d.cycle)} · Plan V${E(d.planVersion??'—')} · Huella ${E(d.fingerprint??'—')}</p>${grid}<details><summary>Detalle de registros y asistencias originales</summary><div style="overflow-x:auto"><table class="table"><thead><tr><th>Periodo / materia</th><th>Notas</th><th>Presentes / faltas / retardos / justificadas / sin marca</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>P${E(r.period)} · ${E(r.subject)}</td><td>${cell(r)}</td><td>${[r.present,r.absent,r.late,r.justified,r.unknown].map(display).join(' / ')}</td></tr>`).join('')}</tbody></table></div></details>`;
}
async function historicalReport(download=true){await show('jop_report',async()=>{const student=value('jop_student')?.trim(),c=cycle();if(!/^[1-9]\d{0,18}$/.test(student||''))throw Error('ID interno inválido.');const d=await request(query('historical_report')+'&student='+encodeURIComponent(student));if(student!==value('jop_student')?.trim()||c!==cycle())return 'Vuelve a consultar.';if(d.student!==student||d.cycle!==c||d.official!==false||typeof d.csv!=='string')throw Error('Informe incompatible.');if(download){const url=URL.createObjectURL(new Blob([d.csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`JAGUAR-REVISION-${c}-${student}.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}return `<p>Informe de revisión: ${E(d.rows.length)} registros. Estado ${E(d.state)}. No es una boleta oficial.</p>${historicalTable(d)}`;});}
let groupCache=null,enrollCache=null;
const groupInput=()=>value('jop_enroll_group')?.trim();
function selection(){const g=groupInput();if(!/^[1-9]\d{0,18}$/.test(g||''))throw Error('ID de grupo inválido.');return g;}
async function cycleGroup(){groupCache=null;await show('jop_group_status',async()=>{const group=selection(),c=cycle(),d=await request(query('cycle_group')+'&group='+encodeURIComponent(group));if(group!==groupInput()||c!==cycle())return 'Vuelve a consultar.';groupCache={group,c,d};return `<p>${E(d.name)} · ${E(d.cycle)} · plan V${E(d.version)} · ${E(d.occupancy)} alumnos</p>${d.binding?`<p>Vinculado a ${E(d.binding.cycle)} · cupo ${E(d.binding.capacity)} · ${d.binding.current?'Vigente':'No vigente'}</p>`:d.valid&&d.empty?'<p>Catálogo compatible y sin alumnos ni notas registradas.</p>':'<p>Grupo no elegible para vinculación.</p>'}${d.canBind?'<label>Cupo autorizado<input id="jop_group_capacity" type="number" min="1" max="500" class="input"></label><button class="btn primary" type="button" onclick="jaguarOperations.bindGroup()">Vincular grupo en pruebas</button>':''}`;});}
async function bindGroup(){const t=groupCache;if(busy||!t?.d.canBind||t.c!==cycle()||t.group!==groupInput())return;const capacity=Number(value('jop_group_capacity')),reference=prompt('Referencia documental de grupo y cupo');if(!Number.isInteger(capacity)||capacity<1||capacity>500||!reference||reference.trim().length<5||!confirm('¿Vincular grupo vacío al plan de destino SOLO en pruebas?'))return;busy=true;try{await request('',{action:'bind_cycle_group',cycle:t.c,group:t.group,capacity,fingerprint:t.d.fingerprint,reference,confirmed:true});toast('Vínculo registrado.');}catch(e){toast(e.message);return;}finally{busy=false;}await cycleGroup();}
async function reenrollment(){enrollCache=null;await show('jop_enroll_status',async()=>{const group=selection(),student=value('jop_student')?.trim(),c=cycle();if(!/^[1-9]\d{0,18}$/.test(student||''))throw Error('ID interno inválido.');const d=await request(query('reenrollment')+'&student='+encodeURIComponent(student)+'&group='+encodeURIComponent(group));if(group!==groupInput()||student!==value('jop_student')?.trim()||c!==cycle())return 'Vuelve a consultar.';enrollCache={group,student,c,d};return `<p>${E(continuityLabels[d.decision.state]||d.decision.state)}</p>${d.destination?`<p>Destino ${E(d.destination.name)} · ${E(d.destination.cycle)} · cupo ${E(d.destination.binding?.capacity)} · ocupación ${E(d.destination.occupancy)}</p>`:''}${d.confirmation?.state==='confirmada'?'<p>Continuidad confirmada por el alumno.</p>':'<p>Sin confirmación vigente del alumno.</p>'}${d.record?`<p>Reinscripción registrada ${E(d.record.id)} · ${E(d.record.reference)} · ${d.record.current?'Vigente':'Revisar evidencia'}</p>`:d.eligible?'<p>Dictamen y destino compatibles.</p>':`<p>${E(d.reason||'No elegible: revisa el dictamen, cierre, ciclo activo, fecha, grupo y cupo.')}</p>`}${d.canEnroll?'<button class="btn primary" type="button" onclick="jaguarOperations.formalizeReenrollment()">Formalizar reinscripción en pruebas</button>':''}<p>La operación cambia el grupo actual; conserva matrícula, notas y asistencias. No aplica a repetición parcial ni inscripción provisional.</p>`;});}
async function formalizeReenrollment(){const t=enrollCache;if(busy||!t?.d.canEnroll||t.c!==cycle()||t.group!==groupInput()||t.student!==value('jop_student')?.trim())return;const reference=prompt('Referencia documental de reinscripción'),reason=reference&&prompt('Motivo administrativo de reinscripción');if(!reference||reference.trim().length<5||!reason||reason.trim().length<15||!confirm('¿Formalizar reinscripción SOLO en el clon de pruebas? Se cambia el grupo actual.'))return;busy=true;try{await request('',{action:'formalize_reenrollment',cycle:t.c,group:t.group,student:t.student,fingerprint:t.d.fingerprint,destinationFingerprint:t.d.destination.fingerprint,reference,reason,confirmed:true});toast('Reinscripción experimental registrada.');}catch(e){toast(e.message);return;}finally{busy=false;}await reenrollment();}
let movementCache=null;
function clearMovement(){movementCache=null;const el=document.getElementById('jop_move_status'),label=document.getElementById('jop_move_target_label');if(el)el.textContent='';if(label)label.hidden=value('jop_move_type')!=='retorno';}
function movementSelection(){const student=value('jop_student')?.trim(),c=cycle(),type=value('jop_move_type'),group=type==='retorno'?value('jop_move_target')?.trim():null;if(!/^[1-9]\d{0,18}$/.test(student||'')||(type==='retorno'&&!/^[1-9]\d{0,18}$/.test(group||'')))throw Error('Indica el ID del alumno y, para retorno, el grupo destino.');return {student,c,type,group};}
async function schoolMovement(){movementCache=null;await show('jop_move_status',async()=>{const sel=movementSelection(),d=await request(query('school_movement')+'&student='+encodeURIComponent(sel.student)+'&type='+sel.type+(sel.group?'&group='+encodeURIComponent(sel.group):''));movementCache={...sel,d};return `<p>Estado actual: <b>${E(d.before.state)}</b> · grupo ${E(d.before.group||'sin grupo')}</p><p>${d.eligible?'Caso elegible para revisión experimental.':'Movimiento no ejecutable en esta modalidad.'}</p>${(d.blockers||[]).map(x=>`<p>${E(x)}</p>`).join('')}${d.canPropose?'<button class="btn" type="button" onclick="jaguarOperations.submitMovement(\'propose\')">Proponer movimiento en pruebas</button>':''}<h5>Historial</h5>${(d.history||[]).map((r,i)=>`<div class="card space-y-1"><b>Registro ${E(r.id)} · ${E(r.type)} · ${E(r.cycle)}</b><p>${E(({pending:'Pendiente de Dirección',applied:'Aplicado en pruebas',rejected:'Rechazado'})[r.state]||r.state)} · ${E(r.reference)} · ${E(r.actor)}</p><p>${E(r.reason)}</p>${r.resolution?`<p>${E(r.resolution.before.state)} → ${E(r.resolution.after.state)} · ${E(r.resolution.reference)} · ${E(r.resolution.actor)}</p>`:''}${r.canApprove?`<button class="btn" type="button" onclick="jaguarOperations.submitMovement('approve',${i})">Autorizar y aplicar en pruebas</button>`:''}${r.canReview?`<button class="btn" type="button" onclick="jaguarOperations.submitMovement('reject',${i})">Rechazar propuesta</button>`:''}${r.state==='pending'&&!r.canReview?'<p>Selecciona el ciclo, tipo y destino de esta propuesta para revisarla.</p>':''}</div>`).join('')||'<p>Sin movimientos V25.</p>'}<p>Solo clon aislado. El estado de cuenta, documento de traslado y conciliación de periodos iniciados requieren procedimientos separados.</p>`;});}
async function submitMovement(operation,index){const t=movementCache;if(busy||!t)return;try{const sel=movementSelection();if(['student','c','type','group'].some(k=>sel[k]!==t[k]))throw Error('Vuelve a consultar el movimiento.');const r=t.d.history?.[index];if(operation==='propose'?!t.d.canPropose:operation==='approve'?!r?.canApprove:operation==='reject'?!r?.canReview:true)return;const reference=prompt('Referencia documental de solicitud o resolución'),reason=reference&&prompt('Motivo de movimiento (mínimo 15 caracteres)');if(!reference||reference.trim().length<5||!reason||reason.trim().length<15||!confirm('¿Registrar '+operation+' SOLO en el clon de pruebas?'))return;busy=true;await request('',{action:'school_movement',operation,student:t.student,cycle:t.c,type:t.type,group:t.group,id:r?.id,fingerprint:r?.fingerprint||t.d.fingerprint,reference,reason,confirmed:true});busy=false;await schoolMovement();}catch(e){toast(e.message,'error');}finally{busy=false;}}

let egressCache=null;
async function egress(){egressCache=null;await show('jop_egress',async()=>{const student=value('jop_student')?.trim(),c=cycle();if(!/^[1-9]\d{0,18}$/.test(student||''))throw Error('ID interno inválido.');const d=await request(query('egress_status')+'&student='+encodeURIComponent(student));if(student!==value('jop_student')?.trim()||c!==cycle())return 'Vuelve a consultar.';egressCache={student,c,d};return `<h4>Egreso administrativo experimental</h4>${d.record?`<p>Registro ${E(d.record.id)} · ${E(d.record.reference)} · ${E(d.record.actor)} · ${d.record.current?'Evidencia vigente':'Evidencia modificada; requiere revisión'}</p>`:d.eligible?'<p>Expediente elegible y dictamen vigente. La formalización cambia el estado del alumno y retira su grupo actual.</p>':'<p>No elegible: requiere dictamen de conclusión académica vigente, último periodo concluido del ciclo actual y grupo de tercero conciliado.</p>'}${d.canFormalize?'<button type="button" class="btn primary" onclick="jaguarOperations.formalizeEgress()">Formalizar egreso en pruebas</button>':''}<p>Sin condición financiera. Solo clon aislado; no elimina expediente ni modifica calificaciones.</p>`;});}
async function formalizeEgress(){const t=egressCache;if(busy||!t?.d.canFormalize||t.student!==value('jop_student')?.trim()||t.c!==cycle())return;const reference=prompt('Referencia documental del egreso (5 a 300 caracteres)'),reason=reference&&prompt('Motivo administrativo de formalización (15 a 1500 caracteres)');if(!reference||reference.trim().length<5||!reason||reason.trim().length<15||!confirm('¿Formalizar egreso SOLO en el clon de pruebas? Cambia estado a egresado y retira el grupo actual.'))return;busy=true;try{await request('',{action:'formalize_egress',cycle:t.c,student:t.student,fingerprint:t.d.fingerprint,reference,reason,confirmed:true});toast('Egreso experimental registrado.');}catch(e){toast(e.message);return;}finally{busy=false;}await egress();}
let continuityCache=null;
const continuityLabels={academic_completion:'Conclusión académica; egreso administrativo pendiente',promotion_eligible:'Elegible para promoción y reinscripción',repeat_grade:'Repetición del grado completo',repeat_subjects:'Repetición de materias pendientes',provisional_eligible:'Reinscripción provisional sin promoción',pending:'Pendiente de revisión'};
async function continuity(){continuityCache=null;await show('jop_continuity',async()=>{const student=value('jop_student')?.trim(),c=cycle();if(!/^[1-9]\d{0,18}$/.test(student||''))throw Error('ID interno inválido.');const d=await request(query('continuity')+'&student='+encodeURIComponent(student));if(student!==value('jop_student')?.trim()||c!==cycle())return 'Vuelve a consultar.';continuityCache={student,c,d};const x=d.decision;return `<h4>Continuidad y conclusión académica</h4><p><b>${E(continuityLabels[x.state]||x.state)}</b></p>${x.reason?`<p>${E(x.reason)}</p>`:''}${x.targetCycle?`<p>Ciclo previsto ${E(x.targetCycle)} · grado ${E(x.targetGrade)} · ${E(x.groupDistribution)}</p>`:''}${x.subjects?.length?`<p>Materias a repetir: ${E(x.subjects.join(', '))}. Requiere conciliación con plan siguiente.</p>`:''}${x.state==='academic_completion'?'<p>Constancia de no adeudo: revisión administrativa separada; no modifica conclusión académica.</p>':''}${d.canRecord?'<button type="button" class="btn primary" onclick="jaguarOperations.recordContinuity()">Registrar determinación experimental</button>':''}<h5>Historial de verificaciones de Control Escolar</h5>${d.history.map(r=>`<p>${E(continuityLabels[r.decision.state]||r.decision.state)} · ${E(r.reference)} · ${E(r.actor)} · ${r.current?'Evidencia vigente':'Evidencia sustituida; requiere revisión'}</p>`).join('')||'<p>Sin verificaciones.</p>'}<p>No asigna grupo, inscribe ni formaliza egreso.</p>`;});}
async function recordContinuity(){const t=continuityCache;if(busy||!t?.d.canRecord||t.student!==value('jop_student')?.trim()||t.c!==cycle())return;const reference=prompt('Referencia documental (5 a 300 caracteres)'),reason=reference&&prompt('Motivo de revisión del expediente (15 a 1500 caracteres)');if(!reference||reference.trim().length<5||!reason||reason.trim().length<15||!confirm('¿Registrar determinación experimental sin cambiar grupo ni matrícula?'))return;busy=true;try{await request('',{action:'record_continuity',cycle:t.c,student:t.student,fingerprint:t.d.fingerprint,reference,reason,confirmed:true});toast('Determinación registrada.');}catch(e){toast(e.message);return;}finally{busy=false;}await continuity();}
async function lateEntry(){await show('jop_late_result',async()=>{const c=cycle(),grade=Number(value('jop_late_grade')),date=value('jop_late_date');if(!date)throw Error('Indica la fecha de ingreso.');const d=await request('?cycle='+encodeURIComponent(c)),row=(d.rows||[]).find(r=>r.estado==='validada_para_planificacion');if(!row)throw Error('Se requiere un plan validado.');const r=await request('',{action:'simulate',kind:'late_entry',plan:row.plan,scenario:{grade,date}});return `<p>Plan V${E(row.version)} · Incorporación en periodo ${E(r.entry)}.</p>${r.subjects.map(m=>`<details><summary>${E(m.name)}</summary>${m.obligations.map(o=>`<p>P${E(o.period)} · ${o.grade==null?'Pendiente de primer resultado':E(o.grade)} · recuperación obligatoria · asistencia no aplicable</p>`).join('')||'<p>No tiene periodos anteriores.</p>'}</details>`).join('')}<p>Valores propuestos; no se ha registrado asistencia, calificación ni inscripción.</p>`;});}
function callInfo(r){const k=r.reglas||{};return `<details class="card"><summary>${E(r.nombre)} · ${E(r.estado)} · V${E(r.version)}</summary><p>Plan V${E(r.plan_version)} · ${E(k.subjectKey)} · ${E(k.start)} — ${E(k.end)}</p><p>${E(k.kind==='recovery'?'Recuperación':'Recursamiento')} · ${E(k.method)} · Tope ${E(k.cap??'AP/RP')} · Asistencia ${E(k.attendancePct)} % · Cupo ${E(k.capacity)} · Intentos ${E(k.attempts)}</p><p>Bloques: ${(k.blocks||[]).map(b=>`P${E(b.period)} (${E(b.minutes)} min)`).join(' · ')}</p>${/^[1-9]\d*$/.test(r.id)?`<button class="btn" type="button" onclick="jaguarOperations.resultPanel('${r.id}')">Simular resultado por bloques</button><div id="jop_result_${E(r.id)}"></div>`:''}${k.kind==='recovery'&&/^[1-9]\d*$/.test(r.id)&&r.estado==='autorizada_para_planeacion'?`<button type="button" class="btn" onclick="jaguarOperations.recoveryCandidate('${r.id}')">Consultar candidatura de recuperación</button><div id="jop_recovery_${E(r.id)}"></div>`:''}${k.kind==='recovery'&&/^[1-9]\d*$/.test(r.id)&&r.estado!=='propuesta'?`<button type="button" class="btn" onclick="jaguarOperations.recoveryWorkflow('${r.id}')">Gestionar expediente de recuperación</button><div id="jop_recovery_work_${E(r.id)}"></div>`:''}${k.kind==='recourse'&&/^[1-9]\d*$/.test(r.id)?`<button type="button" class="btn" onclick="jaguarOperations.roster('${r.id}')">Padrón preparatorio</button><div id="jop_roster_${E(r.id)}"></div><button type="button" class="btn" onclick="jaguarOperations.temporary('${r.id}')">Programar sesiones y docentes de apoyo</button><div id="jop_temp_${E(r.id)}"></div><button type="button" class="btn" onclick="jaguarTemporaryGroup.group('${r.id}')">Consultar grupo temporal</button><div id="jtg_${E(r.id)}"></div><button type="button" class="btn" onclick="jaguarTemporaryGroup.review('${r.id}')">Revisar resultados registrados</button><div id="jtg_review_${E(r.id)}"></div><button type="button" class="btn" onclick="jaguarTemporaryResolution.act('${r.id}')">Consultar acta e intentos</button><div id="jtr_act_${E(r.id)}"></div>`:''}${(r.eventos||[]).map(e=>`<p class="text-sm">V${E(e.version)}: ${E(e.estado)} · ${E(e.actor_nombre)} · ${E(e.motivo)}</p>`).join('')}${S.role==='coordinacion_academica'&&r.estado!=='cancelada'&&/^[1-9]\d*$/.test(r.id)?`${r.estado==='propuesta'?`<button class="btn" onclick="jaguarOperations.transition('${r.id}',${Number(r.version)},'autorizar')">Autorizar para planificación</button>`:''} <button class="btn" onclick="jaguarOperations.transition('${r.id}',${Number(r.version)},'cancelar')">Cancelar antes del inicio</button>`:''}</details>`;}
function callEditor(){if(!plan||!plan.curriculum?.some(s=>s.evaluation!=='no_aplica'))return '<p>Se requiere un plan validado con materias evaluables.</p>';return `<form class="card space-y-2" onsubmit="jaguarOperations.create(event)"><h4>Proponer convocatoria · Plan V${E(planVersion)}</h4><label>Tipo<select id="jop_kind" class="input" onchange="jaguarOperations.callDefaults()"><option value="recovery">Recuperación</option><option value="recourse">Recursamiento</option></select></label><label>Asignatura<select id="jop_subject" class="input" onchange="jaguarOperations.callDefaults()">${plan.curriculum.filter(s=>s.evaluation!=='no_aplica').map(s=>`<option value="${E(s.key)}">${E(s.name)} · ${E(s.grade)}°</option>`).join('')}</select></label><div class="grid md:grid-cols-2 gap-2"><label>Inicio<input id="jop_start" type="date" class="input" required></label><label>Fin<input id="jop_end" type="date" class="input" required></label><label>Modalidad<input id="jop_modality" class="input" minlength="3" maxlength="120" required placeholder="Sabatino, intensivo…"></label><label>Turno<select id="jop_turn" class="input"><option>MATUTINO</option><option>VESPERTINO</option></select></label><label>Letra (si la plantilla la requiere)<input id="jop_letter" class="input" maxlength="1" pattern="[A-Z]"></label><label>Cupo<input id="jop_capacity" type="number" class="input" min="1" max="1000" value="20" required></label><label>Asistencia propia (%)<input id="jop_attendance" type="number" class="input" min="0" max="100" step="0.1" value="80" required></label><label>Intentos<input id="jop_attempts" type="number" class="input" min="1" max="10" value="1" required></label><label>Elegibilidad<select id="jop_eligibility" class="input"><option value="failed">Adeudos</option><option value="improve">También mejora de nota</option></select></label><label>Docente<select id="jop_teacher" class="input"><option value="either">Titular o apoyo</option><option value="holder">Titular</option><option value="support">Apoyo</option></select></label><label>Método<select id="jop_method" class="input"><option value="direct">Directo</option><option value="proportional">Proporcional</option><option value="qualitative">AP/RP</option></select></label><label>Tope<input id="jop_cap" type="number" class="input" min="${E(plan.policy.minimum)}" max="10" step="0.01" value="${E(plan.policy.recoveryCap)}"></label></div><p>Bloques objetivo. En recuperación selecciona uno; en recursamiento puedes definir varios. Duración de cada bloque en minutos.</p>${Array.from({length:plan.policy.periods},(_,i)=>`<div class="flex gap-2 items-center"><label><input id="jop_b${i+1}" type="checkbox"> P${i+1}</label><input id="jop_m${i+1}" aria-label="Minutos bloque ${i+1}" type="number" class="input" min="1" max="525600" value="120"></div>`).join('')}<label>Justificación<textarea id="jop_reason" class="input" minlength="15" maxlength="1500" required></textarea></label><button class="btn primary" type="submit">Registrar propuesta</button><p>Aún no crea grupos, publica convocatoria ni inscribe alumnos.</p></form>`;}
async function calls(){await show('jop_calls',async()=>{const c=cycle(),q=query('calls');const [result,details]=await Promise.all([request(q),request('?cycle='+encodeURIComponent(c))]);if(c!==cycle())return '';const v=(details.rows||[]).find(r=>r.estado==='validada_para_planificacion');plan=v?.effectivePlan||v?.plan||null;planVersion=v?.version||null;loadedCycle=c;availableCalls=result;availablePlans=details.rows||[];return `${S.role==='coordinacion_academica'?callEditor():''}${result.map(callInfo).join('')||'<p>Sin convocatorias.</p>'}`;});callDefaults();}
function callDefaults(){if(!plan||!document.getElementById('jop_kind'))return;const rec=value('jop_kind')==='recourse',qual=plan.curriculum.find(s=>s.key===value('jop_subject'))?.evaluation==='cualitativa';const set=(id,v,locked)=>{const el=document.getElementById(id);if(!el)return;el.value=v;el.disabled=locked;};set('jop_method',qual?'qualitative':rec?plan.policy.recourseMethod:plan.policy.recoveryMethod,qual||rec);set('jop_cap',qual?'':rec?plan.policy.recourseCap:plan.policy.recoveryCap,qual||rec);set('jop_attempts',1,rec);set('jop_teacher',rec?'support':'either',rec);set('jop_eligibility','failed',rec);}
async function mutate(b){if(busy)return;busy=true;try{await request('',b);toast('Operación registrada.');}catch(e){toast(e.message);return;}finally{busy=false;}await calls();}
async function create(e){e.preventDefault();if(busy||!plan||cycle()!==loadedCycle)return;const blocks=Array.from({length:plan.policy.periods},(_,i)=>i+1).filter(i=>document.getElementById('jop_b'+i)?.checked).map(i=>({period:i,minutes:Number(value('jop_m'+i))}));const rules={kind:value('jop_kind'),subjectKey:value('jop_subject'),start:value('jop_start'),end:value('jop_end'),modality:value('jop_modality'),turn:value('jop_turn'),letter:value('jop_letter')||null,capacity:Number(value('jop_capacity')),attendancePct:Number(value('jop_attendance')),attempts:Number(value('jop_attempts')),eligibility:value('jop_eligibility'),teacherMode:value('jop_teacher'),method:value('jop_method'),cap:value('jop_cap')===''?null:Number(value('jop_cap')),blocks};if(!confirm('¿Registrar una propuesta sin crear inscripciones?'))return;await mutate({action:'regularization_call',operation:'proponer',version:0,cycle:loadedCycle,planVersion,rules,reason:value('jop_reason'),confirmed:true});}
async function transition(id,version,operation){if(loadedCycle!==cycle())return;const reason=prompt('Motivo (mínimo 15 caracteres)');if(!reason||reason.trim().length<15)return;if(!confirm('Confirma la operación de planificación. No afecta inscripciones ni notas.'))return;await mutate({action:'regularization_call',operation,id,version,cycle:loadedCycle,reason,confirmed:true});}
const hours=m=>Number.isFinite(m)?(m/60).toFixed(2)+' h':'—';
async function workload(){await show('jop_workload',async()=>{const d=await request(query('teacher_workload'));return `<p>${E(d.limitations)}</p><p>Franjas sin docente: ${E(d.unassigned)} · Franjas inválidas: ${E(d.invalid)} · Franjas sin ciclo en catálogo: ${E(d.unscoped)} (excluidas).</p>${d.teachers.map(t=>`<details class="card"><summary>${E(t.name)} · clases ${hours(t.weeklyTeaching)} · huecos ${hours(t.weeklyGaps)}${t.conflicts?' · ⚠ traslape':''}</summary><p>Permanencia semanal estimada entre clases: ${hours(t.weeklySpan)}</p>${t.days.map(v=>`<p>Día ${E(v.day)}: ${hours(v.teaching)} clases, ${hours(v.span)} permanencia, ${hours(v.gaps)} huecos, máximo intervalo ${hours(v.largestGap)} ${v.overlap?'· traslape':''}</p>`).join('')}</details>`).join('')||'<p>Sin franjas registradas para el ciclo.</p>'}`;});}
function scenarioFor(c,pl){const s=pl.curriculum.find(s=>s.key===c.reglas.subjectKey);if(!s)throw Error('Asignatura no disponible.');const q=s.evaluation==='cualitativa';return {cause:'academic',usedAttempts:0,periodRows:Array.from({length:pl.policy.periods},()=>({...q?{result:'RP'}:{original:5,official:5},attendance:{present:10,absent:0}})),blocks:c.reglas.blocks.map(b=>({period:b.period,state:'completed',...q?{result:'AP'}:{grade:9},attendance:{present:10,absent:0}}))};}
function resultPanel(key){if(!/^[1-9]\d*$/.test(key)||loadedCycle!==cycle())return;const c=availableCalls.find(r=>r.id===key),pl=availablePlans.find(r=>r.version===c?.plan_version&&r.estado==='validada_para_planificacion')?.plan,el=document.getElementById('jop_result_'+key);if(!el)return;if(!c||!pl){el.textContent='Falta la versión exacta del plan de la convocatoria.';return;}try{el.innerHTML=`<form class="card space-y-2" onsubmit="jaguarOperations.simulateResult(event,'${key}')"><p>Datos ficticios de prueba: no incluir matrícula, nombre ni otro identificador. Edita el ejemplo para comprobar el tratamiento de notas, asistencia e intentos.</p><label>Escenario<textarea class="input" id="jop_scenario_${key}" rows="10" required>${E(JSON.stringify(scenarioFor(c,pl),null,2))}</textarea></label><button class="btn" type="submit">Calcular resultado sin registrar</button></form><div id="jop_out_${key}"></div>`;}catch(e){el.textContent=e.message;}}
async function simulateResult(e,key){e.preventDefault();const c=availableCalls.find(r=>r.id===key),pl=availablePlans.find(r=>r.version===c?.plan_version&&r.estado==='validada_para_planificacion')?.plan;if(!c||!pl||loadedCycle!==cycle())return;await show('jop_out_'+key,async()=>{const raw=value('jop_scenario_'+key);if(raw.length>20000)throw Error('Escenario demasiado grande.');const result=await request('',{action:'simulate',kind:'regularization',plan:pl,call:c.reglas,scenario:JSON.parse(raw)});return `<p><b>Resultado de simulación: ${E(result.state)}</b></p><p>${E(result.reason||result.finalAccreditation||'')}</p>${(result.blocks||[]).map(b=>`<p>P${E(b.period)} · ${E(b.state)} · escala: ${E(b.precisionReview?'solo aproximación; requiere representación autorizada':b.adjusted??'—')}</p>`).join('')}<p>Intentos restantes: ${E(result.attemptsRemaining??'Por revisar')}</p><p>Las notas y la inscripción no se modifican.</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${E(JSON.stringify(result,null,2))}</pre>`;});}

const rosterQuery=(view,key,student)=>'?view='+view+'&call='+encodeURIComponent(key)+(student?'&student='+encodeURIComponent(student):'');
const validId=id=>typeof id==='string'&&/^[1-9]\d{0,18}$/.test(id);
let candidateCache=new Map();
function activeCall(key){return validId(key)&&loadedCycle===cycle()?availableCalls.find(c=>c.id===key&&c.reglas?.kind==='recourse'):null;}
async function roster(key){if(!activeCall(key))return;candidateCache.delete(key);await show('jop_roster_'+key,async()=>{const c=activeCall(key),d=await request(rosterQuery('recourse_roster',key));const writable=d.experimental&&S.role==='coordinacion_academica';return `<section class="card space-y-2"><h4>Padrón preparatorio · ${E(c.nombre)}</h4><p>Reserva de cupo y bloques; no abre acceso docente ni consume un intento.</p><p>${d.rows.filter(r=>r.state==='reservada').length} / ${E(c.reglas.capacity)} reservas vigentes.</p>${d.rows.map(r=>`<div class="card"><p>Alumno ${E(r.student)} · ${E(r.state)} · ${E(r.cause)} · P${E(r.blocks.join(', P'))}</p>${(r.events||[]).map(v=>`<p class="text-sm">${E(v.estado)} · ${E(v.actor_nombre)} · ${E(v.motivo)}</p>`).join('')}${writable&&r.state==='reservada'&&validId(r.id)&&validId(r.student)&&Number.isSafeInteger(r.version)?`<button class="btn" onclick="jaguarOperations.cancelReservation('${key}','${r.id}','${r.student}',${r.version})">Cancelar reserva</button>`:''}</div>`).join('')}${c.estado==='autorizada_para_planeacion'?`<label>ID interno del expediente<input class="input" id="jop_candidate_${key}" inputmode="numeric"></label><button class="btn" onclick="jaguarOperations.candidate('${key}')">Comprobar candidatura sellada</button><div id="jop_candidate_result_${key}"></div>`:''}${!d.experimental?'<p>Escrituras deshabilitadas fuera de pruebas.</p>':''}</section>`;});}
async function candidate(key){const student=value('jop_candidate_'+key)?.trim();if(!activeCall(key))return;candidateCache.delete(key);await show('jop_candidate_result_'+key,async()=>{if(!validId(student))throw Error('ID interno inválido.');const d=await request(rosterQuery('recourse_candidate',key,student));if(!activeCall(key)||value('jop_candidate_'+key)?.trim()!==student)return 'Vuelve a consultar.';candidateCache.set(key,{student,data:d});return `<p>Alumno ${E(student)} · Causa: ${E(d.cause)} · Plan V${E(d.planVersion)}.</p><p>Bloques sugeridos: ${E(d.suggested.join(', ')||'Revisión de Coordinación')} · Cupo: ${E(d.reserved)} / ${E(d.capacity)}</p>${!d.allSuggestedAvailable?'<p>La convocatoria no cubre todos los bloques sugeridos. Revisa otra convocatoria.</p>':''}${d.needsReview?'<p>Coordinación debe justificar su selección de bloques.</p>':''}${d.experimental&&S.role==='coordinacion_academica'?`<form onsubmit="jaguarOperations.reserve(event,'${key}')">${d.available.filter(p=>Number.isInteger(p)&&p>=1&&p<=6).map(p=>`<label><input type="checkbox" id="jop_res_${key}_${p}" ${d.suggested.includes(p)?'checked':''} ${d.mandatory.includes(p)?'disabled':''}> P${p}${d.mandatory.includes(p)?' (requerido)':''}</label> `).join('')}<label>Motivo y selección de bloques<textarea class="input" id="jop_res_reason_${key}" minlength="15" maxlength="1500" required></textarea></label><button class="btn primary" type="submit">Registrar reserva de prueba</button></form>`:''}`;});}
async function reserve(event,key){event.preventDefault();const ctx=candidateCache.get(key);if(busy||!activeCall(key)||!ctx||value('jop_candidate_'+key)?.trim()!==ctx.student)return;const blocks=ctx.data.available.filter(p=>document.getElementById('jop_res_'+key+'_'+p)?.checked);if(!confirm('¿Reservar cupo y bloques sin iniciar clases ni modificar calificaciones?'))return;await rosterMutation(key,{operation:'reservar',student:ctx.student,blocks,fingerprint:ctx.data.fingerprint,reason:value('jop_res_reason_'+key)});}
async function cancelReservation(key,id,student,version){if(!activeCall(key)||busy)return;const reason=prompt('Motivo de cancelación (mínimo 15 caracteres)');if(!reason||reason.trim().length<15||!confirm('¿Cancelar la reserva sin consumir intento?'))return;await rosterMutation(key,{operation:'cancelar',id,student,version,reason});}
async function rosterMutation(key,body){if(busy)return;busy=true;try{await request('',{action:'recourse_roster',call:key,confirmed:true,...body});toast('Reserva actualizada.');}catch(e){toast(e.message);return;}finally{busy=false;}await roster(key);}

const temporaryCache=new Map();
const clock=n=>n===1440?'23:59':String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
function tempRow(key,blocks,s={}){return `<div class="grid md:grid-cols-5 gap-2 items-end jop-temp-row"><label>Bloque<select class="input" data-field="period">${blocks.map(b=>`<option value="${E(b.period)}" ${b.period===s.period?'selected':''}>P${E(b.period)}</option>`).join('')}</select></label><label>Fecha<input type="date" class="input" data-field="date" value="${E(s.date||'')}" required></label><label>Inicio<input type="time" class="input" data-field="start" value="${E(clock(s.start??540))}" required></label><label>Fin<input type="time" class="input" data-field="end" value="${E(clock(s.end??600))}" required></label><button type="button" class="btn" onclick="this.closest('.jop-temp-row').remove()">Quitar</button></div>`;}
function addTemporaryRow(key){const c=activeCall(key),el=document.getElementById('jop_temp_input_'+key);if(!c||!el||el.children.length>=366)return;el.insertAdjacentHTML('beforeend',tempRow(key,c.reglas.blocks,{date:c.reglas.start}));}
function readTempRows(key){const el=document.getElementById('jop_temp_input_'+key);if(!el)throw Error('El editor ya no está disponible.');const minute=v=>{if(!/^\d{2}:\d{2}$/.test(v))throw Error('Completa los horarios.');const [h,m]=v.split(':').map(Number);return h*60+m};return Array.from(el.querySelectorAll('.jop-temp-row')).map(r=>{const v=f=>r.querySelector('[data-field="'+f+'"]').value;return {period:Number(v('period')),date:v('date'),start:minute(v('start')),end:minute(v('end'))}});}

async function temporary(key){if(!activeCall(key))return;temporaryCache.delete(key);await show('jop_temp_'+key,async()=>{const d=await request(rosterQuery('temporary_schedule',key));const prev=d.previous;return `<section class="card space-y-2"><h4>Programación temporal</h4><p>${E(d.start)} — ${E(d.end)} · ${E(d.rosterCount)} reservas vigentes.</p><p>Duración exigida: ${d.blocks.map(b=>`P${E(b.period)}: ${E(b.minutes)} min`).join(' · ')}</p>${prev?`<p>V${E(prev.version)} · ${E(prev.state)} · ${E(prev.actor)} · ${E(prev.reason)}</p>${temporaryRows(prev.schedule?.sessions||[])}${prev.state==='propuesta'&&d.experimental&&S.role==='coordinacion_academica'?`<button type="button" class="btn" onclick="jaguarOperations.cancelTemporary('${key}',${Number(prev.version)})">Cancelar programación propuesta</button>`:''}`:''}${S.role==='coordinacion_academica'?`<form onsubmit="jaguarOperations.previewTemporary(event,'${key}')"><label>Asignación docente<select class="input" id="jop_temp_mode_${key}"><option value="continuity">Priorizar mismo docente para todo el curso</option><option value="per_block">Seleccionar por bloque, priorizando continuidad</option></select></label><p>Distribuye las sesiones fechadas de cada bloque. El motor comprobará minutos, fechas y traslapes.</p><div id="jop_temp_input_${key}" class="space-y-2">${(prev?.schedule?.sessions||d.blocks.map(b=>({period:b.period,date:d.start,start:540,end:540+Math.min(b.minutes,120)}))).map(s=>tempRow(key,d.blocks,s)).join('')}</div><button type="button" class="btn" onclick="jaguarOperations.addTemporaryRow('${key}')">Agregar sesión</button><button class="btn" type="submit">Calcular propuesta docente</button></form><div id="jop_temp_preview_${key}"></div>`:''}<p>Solo propuesta. No crea acceso a expedientes, no consume intento ni inicia clases.</p></section>`;});}
function temporaryRows(rows){return rows.map(s=>`<p>P${E(s.period)} · ${E(s.date)} · ${E(String(Math.floor(s.start/60)).padStart(2,'0'))}:${E(String(s.start%60).padStart(2,'0'))}–${E(String(Math.floor(s.end/60)).padStart(2,'0'))}:${E(String(s.end%60).padStart(2,'0'))} · Docente ${E(s.teacher)}</p>`).join('');}
async function previewTemporary(e,key){e.preventDefault();if(!activeCall(key))return;temporaryCache.delete(key);await show('jop_temp_preview_'+key,async()=>{const sessions=readTempRows(key),raw=JSON.stringify(sessions),mode=value('jop_temp_mode_'+key);const d=await request('',{action:'temporary_schedule',operation:'preview',call:key,sessions,mode});temporaryCache.set(key,{raw,mode,sessions,d});return `<p><b>${E(d.state==='proposed'?'Propuesta compatible con los datos registrados':d.reason)}</b></p>${temporaryRows(d.sessions||[])}<p>${E(d.limitations||'No se asigna automáticamente.')}</p>${d.state==='proposed'&&d.experimental?`<label>Motivo<textarea class="input" id="jop_temp_reason_${key}" minlength="15" maxlength="1500"></textarea></label><button type="button" class="btn primary" onclick="jaguarOperations.saveTemporary('${key}')">Guardar propuesta de prueba</button>`:''}`;});}
async function saveTemporary(key){const c=temporaryCache.get(key);if(!activeCall(key)||busy||!c||c.raw!==JSON.stringify(readTempRows(key))||c.mode!==value('jop_temp_mode_'+key))return toast('Consulta la propuesta vigente.');const reason=value('jop_temp_reason_'+key);if(!reason||reason.trim().length<15||!confirm('¿Guardar solo la programación propuesta?'))return;busy=true;try{await request('',{action:'temporary_schedule',operation:'save',call:key,sessions:c.sessions,mode:c.mode,confirmed:true,reason,version:c.d.version,fingerprint:c.d.fingerprint});toast('Propuesta guardada.');}catch(e){toast(e.message);return;}finally{busy=false;}await temporary(key);}
async function cancelTemporary(key,version){if(!activeCall(key)||busy)return;const reason=prompt('Motivo de cancelación (mínimo 15 caracteres)');if(!reason||reason.trim().length<15||!confirm('¿Cancelar esta propuesta?'))return;busy=true;try{await request('',{action:'temporary_schedule',operation:'cancel',call:key,version,reason,confirmed:true});toast('Propuesta cancelada.');}catch(e){toast(e.message);return;}finally{busy=false;}await temporary(key);}
let openingCache=null;
async function cycleOpening(){openingCache=null;await show('jop_opening',async()=>{const c=cycle(),d=await request(query('cycle_opening'));if(c!==cycle())return 'Vuelve a consultar.';openingCache={c,d};const result=d.result||{};return d.activated?`<p>Ciclo abierto en pruebas. ${E(result.periods)} periodos; ${E(result.archivedGroups)} grupos de origen desactivados; ${E(result.studentMoves)} movimientos individuales.</p>`:`<p>Origen: ${E(d.source)} · versión destino ${E(d.version)}</p><p>Grupos de origen: ${E(d.sourceGroups?.length)} · grupos destino: ${E(d.targetGroups?.length)}</p><p>Periodos: ${E(d.plan?.policy?.periods)} · mínima: ${E(d.plan?.policy?.minimum)} · ${d.plan?.policy?.precision===1?'Un decimal':'Enteros'} · ${d.plan?.policy?.ordinaryRounding==='truncate'?'Truncamiento':'Redondeo al más cercano'}</p>${(d.blockers||[]).map(x=>`<p>${E(x)}</p>`).join('')}${d.canActivate?'<button type="button" class="btn primary" onclick="jaguarOperations.activateCycle()">Abrir ciclo en pruebas</button>':''}<p>La apertura no promueve alumnos; Control Escolar debe formalizar cada reinscripción.</p>`;});}
async function activateCycle(){const t=openingCache;if(busy||!t?.d.canActivate||t.c!==cycle())return;const reference=prompt('Referencia de autorización de apertura'),reason=reference&&prompt('Motivo de apertura (mínimo 15 caracteres)');if(!reference||reference.trim().length<5||!reason||reason.trim().length<15||!confirm('¿Abrir el ciclo SOLO en el clon de pruebas? Se desactivarán los grupos de origen; no se cambiarán matrículas.'))return;busy=true;try{await request('',{action:'activate_cycle',cycle:t.c,fingerprint:t.d.fingerprint,reference,reason,confirmed:true});toast('Apertura experimental registrada.');}catch(e){toast(e.message);return;}finally{busy=false;}await cycleOpening();}
async function recoveryCandidate(id){if(loadedCycle!==cycle()||!/^\d+$/.test(id))return;const student=value('jop_student')?.trim();await show('jop_recovery_'+id,async()=>{if(!/^[1-9]\d*$/.test(student||''))throw Error('Indica el ID del alumno en la consulta de acreditación.');const d=await request('?view=recovery_candidate&call='+encodeURIComponent(id)+'&student='+encodeURIComponent(student));if(student!==value('jop_student')?.trim())return 'Cambió el alumno. Vuelve a consultar.';return `<p>${E(d.name)} · P${E(d.period)} · plan V${E(d.planVersion)}</p><p>${d.eligible?'Candidato preliminar':d.state==='review'?'Evidencia pendiente de revisión':'No elegible según periodo'}${d.reason?' · '+E(d.reason):''}</p><p>Nota fuente ${E(d.original??d.result??'—')} · nota ordinaria ${E(d.ordinary??d.result??'—')}</p>${d.cycleAttendancePending?'<p>Asistencia acumulada todavía pendiente de evaluación.</p>':''}<p>${E(d.notice)}</p>`;});}
let recoveryCache={};
function recoverySessionRow(id){const root=document.getElementById('jop_recovery_sessions_'+id);if(!root||root.children.length>=500)return;const el=document.createElement('div');el.className='grid gap-2 card';el.innerHTML='<label>Fecha <input type="date" data-r-date class="input"></label><label>Inicio <input type="time" data-r-start class="input"></label><label>Fin <input type="time" data-r-end class="input"></label><label>Marca <select class="input" data-r-mark><option value="">Selecciona</option><option value="present">Presente</option><option value="absent">Falta</option><option value="late">Retardo</option><option value="justified">Justificada documentada</option></select></label><label>Referencia de sesión<input data-r-ref maxlength="300" class="input"></label><button type="button" class="btn" onclick="this.parentElement.remove()">Quitar sesión</button>';root.append(el);}
async function recoveryWorkflow(id){if(loadedCycle!==cycle()||!/^[1-9]\d*$/.test(id))return;delete recoveryCache[id];const student=value('jop_student')?.trim(),c=cycle();await show('jop_recovery_work_'+id,async()=>{if(!/^[1-9]\d*$/.test(student||''))throw Error('Indica ID del alumno.');const d=await request('?view=recovery_workflow&call='+encodeURIComponent(id)+'&student='+encodeURIComponent(student));if(student!==value('jop_student')?.trim()||c!==cycle())return 'Cambió el expediente. Vuelve a consultar.';recoveryCache[id]={d,student,c};const rec=d.record,st=rec?.state,ev=rec?.payload,ca=S.role==='coordinacion_academica',dir=S.role==='direccion_escolar',call=availableCalls.find(r=>r.id===id),qual=call?.reglas?.method==='qualitative';const button=(op,label)=>`<button type="button" class="btn" onclick="jaguarOperations.moveRecovery('${id}','${op}')">${label}</button>`;return `<p>Alumno ID ${E(student)} · Estado: ${E(st||'Sin reserva')} · ${E(d.reserved)} / ${E(d.capacity)} cupos · Intentos usados: ${E(d.usedAttempts)} / ${E(d.limit)}</p><p>${d.candidate?.eligible?'Candidatura compatible':E(d.candidate?.reason||'Sin candidatura vigente')}</p>${ev?`<p>Evaluación: ${E(ev.evaluation?.state)} · Nota obtenida: ${E(ev.evidence?.grade??ev.evidence?.result)} · Resultado anterior: ${E(ev.before?.official??ev.before?.result)} · Propuesto: ${E(ev.after?.official??ev.after?.result)}</p><details><summary>Sesiones documentadas para revisar</summary>${(ev.evidence?.sessions||[]).map(s=>`<p>${E(s.date)} ${E(s.start)}–${E(s.end)} · ${E(s.mark)} · ${E(s.reference)}</p>`).join('')}<p>Acta fuente: ${E(ev.evidence?.reference)}</p></details>`:''}${(d.history||[]).map(e=>`<p>V${E(e.version)} · ${E(e.estado)} · ${E(e.cargo)} · ${E(e.referencia)} · ${E(e.motivo)}</p>`).join('')}${!d.experimental?'<p>Escrituras deshabilitadas fuera de pruebas.</p>':`${ca&&!st&&d.candidate?.eligible&&d.usedAttempts<d.limit&&d.reserved<d.capacity?button('reservar','Reservar recuperación'):''}${ca&&st==='reservada'?`${button('cancelar','Cancelar reserva de recuperación')}<details class="card"><summary>Transcribir evaluación documentada</summary><p>Solo después de concluir la convocatoria. Captura las sesiones reales respaldadas por listas y la evaluación firmada; no inventes marcas.</p><label>Acta fuente<input class="input" id="jop_rr_ref_${id}" /></label>${qual?`<label>Resultado<select class="input" id="jop_rr_grade_${id}"><option value="">Selecciona</option><option>AP</option><option>RP</option></select></label>`:`<label>Nota obtenida<input class="input" id="jop_rr_grade_${id}" type="number" min="0" max="10" step="any"></label>`}<div id="jop_recovery_sessions_${id}"></div><button type="button" class="btn" onclick="jaguarOperations.recoverySessionRow('${id}')">Agregar sesión documentada</button>${button('evaluar','Registrar evaluación de recuperación')}</details>`:''}${dir&&st==='evaluada'?button('autorizar','Autorizar resultado de recuperación')+button('rechazar','Rechazar evidencia de recuperación'):''}`}<p>Libro experimental; no modifica calificaciones ordinarias ni boletas.</p>`;});}
async function moveRecovery(id,operation){const t=recoveryCache[id];if(busy||!t||t.c!==cycle()||t.student!==value('jop_student')?.trim())return;let evidence;try{if(operation==='evaluar'){const grade=value('jop_rr_grade_'+id);if(grade==null||grade==='')throw Error('Registra el resultado obtenido.');const call=availableCalls.find(r=>r.id===id),qual=call?.reglas?.method==='qualitative';evidence={reference:value('jop_rr_ref_'+id),...(qual?{result:grade}:{grade:Number(grade)}),sessions:Array.from(document.querySelectorAll('#jop_recovery_sessions_'+id+' > div')).map(el=>Object.fromEntries(['date','start','end','mark','ref'].map(k=>[k==='ref'?'reference':k,el.querySelector('[data-r-'+k+']').value])))};if(!evidence.sessions.length)throw Error('Agrega las sesiones documentadas.');}}catch(e){toast(e.message);return;}
 const reference=prompt('Referencia documental (5 a 300 caracteres)'),reason=reference&&prompt('Motivo (15 a 1500 caracteres)');if(!reference||reference.trim().length<5||!reason||reason.trim().length<15||!confirm('¿Registrar '+operation+' de recuperación solo en el clon de pruebas?'))return;busy=true;try{await request('',{action:'recovery_workflow',call:id,student:t.student,operation,fingerprint:t.d.fingerprint,reference,reason,confirmed:true,...(evidence?{evidence}:{})});toast('Movimiento registrado.');}catch(e){toast(e.message);return;}finally{busy=false;}await recoveryWorkflow(id);}
window.jaguarOperations={clearMovement,schoolMovement,submitMovement,recoveryWorkflow,recoverySessionRow,moveRecovery,recoveryCandidate,cycleOpening,activateCycle,cycleGroup,bindGroup,reenrollment,formalizeReenrollment,egress,formalizeEgress,historicalReport,lateEntry,continuity,recordContinuity,trajectory,applyRecourse,addTemporaryRow,temporary,previewTemporary,saveTemporary,cancelTemporary,roster,candidate,reserve,cancelReservation,resultPanel,simulateResult,html,reset,project,calls,callDefaults,create,transition,workload};})();
